func CountSpaces(r io.Reader) (int, error) {
	buf := make([]byte, 64)
	spaces := 0

	for {
		n, err := r.Read(buf)
		if n > 0 {
			for _, b := range buf[:n] {
				if b == ' ' {
					spaces++
				}
			}
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return spaces, err
		}
	}
	return spaces, nil
}

func main() {
